<script setup lang="ts">
import type { Quote } from '~/utils/quotes'
const props = defineProps<{ quote: Quote; saveWorkspace: () => Promise<void>; refreshWorkspace: () => Promise<void> }>()
const { data: config } = await useFetch('/api/config')
const busy = ref(false), feedback = ref(''), url = ref(''), draft = ref(''), language = ref('English'), purpose = ref('introduction'), emailConfirmed = ref(false)
watch(() => props.quote.id, () => { url.value = ''; draft.value = ''; feedback.value = ''; emailConfirmed.value = false })
async function action(work: () => Promise<void>) {
  busy.value = true; feedback.value = ''
  try { await props.saveWorkspace(); await work() }
  catch (e: any) { feedback.value = e.data?.statusMessage || e.message || 'Operation failed. Please try again.' }
  finally { busy.value = false }
}
function publish() { return action(async () => { const result = await $fetch('/api/quotes/publish', { method: 'POST', body: { quoteId: props.quote.id } }); url.value = result.url; await props.refreshWorkspace(); feedback.value = 'Link created. Previous links for this quote have been revoked.' }) }
function revoke() { return action(async () => { await $fetch('/api/quotes/revoke', { method: 'POST', body: { quoteId: props.quote.id } }); url.value = ''; feedback.value = 'All customer links for this quote have been revoked.' }) }
function generate() { return action(async () => { const result = await $fetch('/api/ai/draft', { method: 'POST', body: { quoteId: props.quote.id, language: language.value, purpose: purpose.value } }); draft.value = result.text; feedback.value = 'AI draft generated. Review all details before copying or sending.' }) }
function email() { return action(async () => { await $fetch('/api/quotes/email', { method: 'POST', body: { quoteId: props.quote.id, token: url.value.split('/').pop(), confirmed: emailConfirmed.value } }); feedback.value = 'Quote email submitted for delivery.'; emailConfirmed.value = false }) }
async function copy(text: string) { try { await navigator.clipboard.writeText(text); feedback.value = 'Copied to clipboard.' } catch { feedback.value = 'Please select and copy the text manually.' } }
</script>
<template><section class="integration-actions"><h3>Customer link & AI drafting</h3><div class="status-actions"><UiButton v-if="['Draft','Sent'].includes(quote.status)" :disabled="busy" @click="publish">{{ busy ? 'Working…' : 'Create customer link' }}</UiButton><UiButton variant="outline" :disabled="busy" @click="revoke">Revoke links</UiButton></div><p class="helper">Publishing marks the quote as sent and freezes its contents. Anyone with the link can view and respond; share only with the intended customer.</p><div v-if="url" class="share-link"><label>Private customer link<input :value="url" readonly aria-label="Private quote link"></label><UiButton variant="outline" @click="copy(url)">Copy link</UiButton><a :href="url" target="_blank" rel="noopener noreferrer" class="text-link">Open customer page</a></div><div v-if="url && config?.email" class="email-confirm"><label class="checkbox-label"><input v-model="emailConfirmed" type="checkbox">Send this quote link to the saved customer email.</label><UiButton :disabled="busy || !emailConfirmed" @click="email">Send quote email</UiButton></div><div class="form-grid ai-options"><label>Language<select v-model="language"><option>English</option><option>Filipino</option></select></label><label>Message type<select v-model="purpose"><option value="introduction">Quote introduction</option><option value="follow-up">Follow-up</option></select></label></div><UiButton variant="outline" :disabled="busy || !config?.ai" @click="generate"><AppIcon name="spark" :size="16" /> Draft with AI</UiButton><p v-if="!config?.ai" class="helper">AI is not configured. Add the server API key and model to enable drafting.</p><template v-if="draft"><label class="draft-label">Review and edit AI draft<textarea v-model="draft" rows="5" /></label><UiButton variant="outline" @click="copy(draft)">Copy reviewed draft</UiButton></template><p v-if="feedback" class="notice" role="status">{{ feedback }}</p></section></template>
